export function resolveAdminConsoleModuleState(
  input: AdminConsoleModuleStateInput,
): AdminConsoleModuleState {
  if (input.isUnauthorized) {
    return "unauthorized";
  }
  if (input.hasError) {
    return "error";
  }
  if (input.isLoading) {
    return "loading";
  }
  if (input.isEmpty) {
    return "empty";
  }
  return "ready";
}

