  try {
    theme = window.localStorage.getItem(key);
  } catch (error) {}
  if (theme !== "light" && theme !== "dark" && theme !== "system") {
    theme = "system";
    try {
      window.localStorage.setItem(key, theme);
    } catch (error) {}
  }
  var resolved = theme === "system"
