function getConfiguredChannelFilter() {
  const channelId = process.env.YOUTUBE_CHANNEL_ID?.trim()
    || process.env.NEXT_PUBLIC_YOUTUBE_CHANNEL_ID?.trim();
  if (channelId) return { channelId, handlePattern: null };

  const configuredHandle = process.env.YOUTUBE_CHANNEL_HANDLE?.trim()
    || process.env.NEXT_PUBLIC_YOUTUBE_CHANNEL_HANDLE?.trim()
    || '@tzuyang6145';
  const handle = `@${configuredHandle.replace(/^@/, '').normalize('NFC').toLowerCase()}`;
  if (!/^@[\p{L}\p{M}\p{N}_.-]+$/u.test(handle)) return null;
  // Escape LIKE metacharacters so configured handles remain exact identities.
  return { channelId: null, handlePattern: handle.replace(/[\\%_]/g, '\\$&') };
}

